export { ChatSession } from "./chat-session";
export { MemoryWorkflow } from "./memory-workflow";

import { MAX_AUDIO_BYTES, MAX_SPEECH_CHARS, synthesize, transcribe } from "./voice";

const SESSION_ID = /^[A-Za-z0-9-]{8,64}$/;
const MAX_MESSAGE_LENGTH = 4000;

function json(data: unknown, status = 200): Response {
	return Response.json(data, { status });
}

function sessionStub(env: Env, sessionId: string) {
	return env.CHAT_SESSION.get(env.CHAT_SESSION.idFromName(sessionId));
}

/** Keyed by client IP rather than sessionId, because session ids are generated by the browser. */
async function isRateLimited(limiter: RateLimit, request: Request): Promise<boolean> {
	const ip = request.headers.get("cf-connecting-ip") ?? "unknown";
	const { success } = await limiter.limit({ key: ip });
	return !success;
}

function tooManyRequests(): Response {
	return Response.json(
		{ error: "Too many requests. Please wait a minute and try again." },
		{ status: 429, headers: { "retry-after": "60" } },
	);
}

/** Workers AI error 4006: the account's daily free allocation of neurons is used up. */
function aiFailure(err: unknown, fallback: string): Response {
	if (String(err).includes("4006")) {
		return json({ error: "The daily Workers AI quota is used up. Please try again tomorrow." }, 429);
	}
	return json({ error: fallback }, 502);
}

async function readBody(request: Request): Promise<Record<string, unknown>> {
	try {
		const body: unknown = await request.json();
		return typeof body === "object" && body !== null ? (body as Record<string, unknown>) : {};
	} catch {
		return {};
	}
}

export default {
	async fetch(request, env): Promise<Response> {
		const url = new URL(request.url);
		const { pathname } = url;

		// POST /api/chat  { sessionId, message, voice? }  ->  text/event-stream of LLM tokens
		if (pathname === "/api/chat" && request.method === "POST") {
			if (await isRateLimited(env.CHAT_LIMITER, request)) return tooManyRequests();
			const { sessionId, message, voice } = await readBody(request);
			if (typeof sessionId !== "string" || !SESSION_ID.test(sessionId)) {
				return json({ error: "Invalid sessionId" }, 400);
			}
			if (typeof message !== "string" || !message.trim() || message.length > MAX_MESSAGE_LENGTH) {
				return json({ error: `Message must be 1-${MAX_MESSAGE_LENGTH} characters` }, 400);
			}
			let stream: ReadableStream<Uint8Array>;
			try {
				stream = await sessionStub(env, sessionId).chat(sessionId, message.trim(), voice === true);
			} catch (err) {
				console.error("chat failed", err);
				return aiFailure(err, "The AI model is unavailable right now. Please try again.");
			}
			return new Response(stream, {
				headers: { "content-type": "text/event-stream", "cache-control": "no-cache" },
			});
		}

		// GET /api/session?sessionId=...  ->  transcript, memory, and latest workflow status
		if (pathname === "/api/session" && request.method === "GET") {
			const sessionId = url.searchParams.get("sessionId") ?? "";
			if (!SESSION_ID.test(sessionId)) return json({ error: "Invalid sessionId" }, 400);
			const stub = sessionStub(env, sessionId);
			const [messages, memory, workflowId] = await Promise.all([
				stub.getMessages(),
				stub.getMemory(),
				stub.getWorkflowId(),
			]);
			let workflow: { id: string; status: string } | null = null;
			if (workflowId) {
				try {
					const status = await (await env.MEMORY_WORKFLOW.get(workflowId)).status();
					workflow = { id: workflowId, status: status.status };
				} catch {
					workflow = { id: workflowId, status: "unknown" };
				}
			}
			return json({ messages, memory, workflow });
		}

		// POST /api/memory/refresh  { sessionId }  ->  start the memory workflow now
		if (pathname === "/api/memory/refresh" && request.method === "POST") {
			if (await isRateLimited(env.MEMORY_LIMITER, request)) return tooManyRequests();
			const { sessionId } = await readBody(request);
			if (typeof sessionId !== "string" || !SESSION_ID.test(sessionId)) {
				return json({ error: "Invalid sessionId" }, 400);
			}
			const id = await sessionStub(env, sessionId).refreshMemory(sessionId);
			if (!id) return json({ error: "Nothing to remember yet. Send a message first." }, 409);
			return json({ workflowId: id }, 202);
		}

		// POST /api/transcribe  (audio/wav body)  ->  { text }
		if (pathname === "/api/transcribe" && request.method === "POST") {
			if (await isRateLimited(env.VOICE_LIMITER, request)) return tooManyRequests();
			const contentType = request.headers.get("content-type") ?? "";
			if (!contentType.startsWith("audio/")) return json({ error: "Expected an audio upload" }, 415);
			if (Number(request.headers.get("content-length")) > MAX_AUDIO_BYTES) {
				return json({ error: "Recordings must be under a minute" }, 413);
			}
			const audio = await request.arrayBuffer();
			if (audio.byteLength === 0) return json({ error: "The recording was empty" }, 400);
			if (audio.byteLength > MAX_AUDIO_BYTES) return json({ error: "Recordings must be under a minute" }, 413);
			try {
				return json({ text: await transcribe(env.AI, audio, contentType) });
			} catch (err) {
				console.error("transcription failed", err);
				return aiFailure(err, "Couldn't transcribe that recording. Please try again.");
			}
		}

		// GET /api/speak?text=...  ->  audio/mpeg, streamed so an <audio> element can play it as it arrives
		if (pathname === "/api/speak" && request.method === "GET") {
			if (await isRateLimited(env.SPEECH_LIMITER, request)) return tooManyRequests();
			const text = url.searchParams.get("text") ?? "";
			if (!text.trim() || text.length > MAX_SPEECH_CHARS) {
				return json({ error: `Text must be 1-${MAX_SPEECH_CHARS} characters` }, 400);
			}
			try {
				return new Response(await synthesize(env.AI, text.trim()), {
					headers: { "content-type": "audio/mpeg", "cache-control": "no-store", "accept-ranges": "none" },
				});
			} catch (err) {
				console.error("speech failed", err);
				return aiFailure(err, "Couldn't generate speech right now.");
			}
		}

		// POST /api/reset  { sessionId }  ->  wipe transcript and memory
		if (pathname === "/api/reset" && request.method === "POST") {
			const { sessionId } = await readBody(request);
			if (typeof sessionId !== "string" || !SESSION_ID.test(sessionId)) {
				return json({ error: "Invalid sessionId" }, 400);
			}
			await sessionStub(env, sessionId).reset();
			return json({ ok: true });
		}

		if (pathname.startsWith("/api/")) return json({ error: "Not found" }, 404);
		return new Response("Not found", { status: 404 });
	},
} satisfies ExportedHandler<Env>;
